set-variable.value:
@{
        try {
            var jwt = ((string)context.Variables["rawBearer"]).AsJwt();
            if (jwt == null) { return ""; }
            string u = null;
            if (jwt.Claims.ContainsKey("preferred_username")) { u = jwt.Claims.GetValueOrDefault("preferred_username",""); }
            if (string.IsNullOrEmpty(u) && jwt.Claims.ContainsKey("email")) { u = jwt.Claims.GetValueOrDefault("email",""); }
            if (string.IsNullOrEmpty(u) && jwt.Claims.ContainsKey("emails")) { u = jwt.Claims.GetValueOrDefault("emails",""); }
            if (string.IsNullOrEmpty(u) && jwt.Claims.ContainsKey("upn")) { u = jwt.Claims.GetValueOrDefault("upn",""); }
            return u ?? "";
        } catch { return ""; }
    }

@{
        try {
            var raw = context.Request.Body.As<string>(preserveContent: true);
            if (string.IsNullOrEmpty(raw)) { return false; }
            var body = JObject.Parse(raw);
            var claim = (string)context.Variables["citizenUpn"];
            var subjectId = body["subjectId"];
            if (subjectId != null) {
                var value = subjectId.ToString();
                if (!string.IsNullOrEmpty(value) && value.ToLowerInvariant() != claim.ToLowerInvariant()) { return true; }
            }
            var citizen = body["citizenUpn"];
            if (citizen != null) {
                var value = citizen.ToString();
                if (!string.IsNullOrEmpty(value) && value.ToLowerInvariant() != claim.ToLowerInvariant()) { return true; }
            }
            return false;
        } catch { return false; }
    }
